@Entry
@Component
struct ImageWidthPage {
  @State imageWidth: number = 120

  build() {
    Column({ space: 12 }) {
      Image($r('app.media.icon')).width(this.imageWidth)
      TextInput({ text: String(this.imageWidth) })
        .type(InputType.Number)
        .onChange(value => {
          const width = Number(value)
          if (width >= 100 && width <= 300) this.imageWidth = width
        })
      Row() {
        Button('减小').onClick(() => this.imageWidth = Math.max(100, this.imageWidth - 10))
        Button('增大').onClick(() => this.imageWidth = Math.min(300, this.imageWidth + 10))
      }
      Slider({ value: this.imageWidth, min: 100, max: 300, step: 10 })
        .onChange(value => this.imageWidth = value)
      Text(`当前宽度：${this.imageWidth}`)
    }
    .padding(20)
  }
}

