@Entry
@Component
struct LoginFlow {
  @State page: string = 'login'

  build() {
    Navigation() {
      Column({ space: 12 }) {
        if (this.page === 'login') {
          TextInput({ placeholder: '用户名' })
          TextInput({ placeholder: '密码' }).type(InputType.Password)
          Button('登录').onClick(() => this.page = 'profile')
          Button('去注册').onClick(() => this.page = 'register')
        } else if (this.page === 'register') {
          TextInput({ placeholder: '用户名' })
          TextInput({ placeholder: '密码' }).type(InputType.Password)
          TextInput({ placeholder: '确认密码' }).type(InputType.Password)
          Button('注册').onClick(() => this.page = 'profile')
          Button('去登录').onClick(() => this.page = 'login')
        } else {
          Text('当前您已登录')
          Button('退出登录').onClick(() => this.page = 'login')
        }
      }
      .padding(20)
    }
    .title('账户')
  }
}

